using System;using System.Collections.Generic;
// Enemy APC ([ai character]) spawn table, GENERATED by local-run/pvf/gen_apc_monsters.py from the
// CN70 PVF through the pvfUtility HTTP API. Shape mirrors ConditionMonstersFG: one row per
// (dungeon, map) APC declaration, {mapIdx, apcId, level, roleNum}.
//   apcId    the first column of the .map [ai character] row (native add_monster_APC_AI actor id).
//   level    aicharacter/aicharacter.lst -> that .aic's [minimum info] 5th field. The same source
//            reproduces the shipped Act4-Boss-Apc-FG176.cs BossApcLevelFG176=47 for 1301.
//   roleNum  5 = [normal], 8 = [boss]; the number is a shipped-code convention, taken from the two
//            existing side-channel writes (GSD companion write sends 5 for [normal], the Act4 boss
//            APC write sends 8), because the [ai character] row carries only the textual tag.
// These actors are NOT room-roster monsters: Offline70DungeonFlowFG writes them in a side channel
// outside TotalCount, so they keep no .mob drop profile (noDrop) and their uid stays outside
// ValidateKill's 100..100+TotalCount monster range. Only [monster]-typed rows are listed;
// [special passive object]/[passive object] rows are destruction targets and stay out.
internal static class ApcMonstersFG {
 // dungeonId -> rows of {mapIdx, apcId, level, roleNum}

 // Every row below is quoted from the PVF (see local-run/pvf/export/apc/apc-citations.txt):
 // d21 map3016  [ai character] id=21400 level=30 role=normal
 // d23 map3418  [ai character] id=1400 level=32 role=normal
 // d24 map3627  [ai character] id=6400 level=33 role=normal
 // d26 map4033  [ai character] id=11400 level=37 role=normal
 // d37 map7027  [ai character] id=1301 level=47 role=boss
 // d42 map9008  [ai character] id=15600 level=45 role=normal
 // d43 map9203  [ai character] id=607 level=47 role=normal
 // d44 map9103  [ai character] id=609 level=50 role=normal
 // d141 map16018  [ai character] id=20607 level=52 role=normal
 internal static readonly Dictionary<ushort,List<ushort[]>> Table =
  new Dictionary<ushort,List<ushort[]>>{
  {21,new List<ushort[]>{new ushort[]{3016,21400,30,5}}},
  {23,new List<ushort[]>{new ushort[]{3418,1400,32,5}}},
  {24,new List<ushort[]>{new ushort[]{3627,6400,33,5}}},
  {26,new List<ushort[]>{new ushort[]{4033,11400,37,5}}},
  {37,new List<ushort[]>{new ushort[]{7027,1301,47,8}}},
  {42,new List<ushort[]>{new ushort[]{9008,15600,45,5}}},
  {43,new List<ushort[]>{new ushort[]{9203,607,47,5}}},
  {44,new List<ushort[]>{new ushort[]{9103,609,50,5}}},
  {141,new List<ushort[]>{new ushort[]{16018,20607,52,5}}},
  };
 internal static bool DeclaresApc(ushort dungeonId,ushort mapIdx){
  List<ushort[]> rows;
  if(!Table.TryGetValue(dungeonId,out rows))return false;
  foreach(ushort[] row in rows)if(row[0]==mapIdx)return true;
  return false;}
 internal static List<ushort[]> GetApcMonsters(ushort dungeonId,ushort mapIdx){
  List<ushort[]> rows;
  if(!Table.TryGetValue(dungeonId,out rows))return new List<ushort[]>();
  List<ushort[]> result=new List<ushort[]>();
  foreach(ushort[] row in rows)if(row[0]==mapIdx)result.Add(row);
  return result;}
}

